from pathlib import Path
import json,re
root=Path('/Users/zen/Project/wavvy')
series=root/'SERIES/20-00'
concept=(series/'concept.md').read_text()
report=json.loads((series/'output/report.json').read_text())
section=concept.split('## Final Track Sources',1)[1]
blocks=re.split(r'^### (\d{2})\. (.+)$', section, flags=re.M)
entries={}
# re.split gives preamble then triplets order,title,body
for i in range(1,len(blocks),3):
    order=int(blocks[i]); title=blocks[i+1].strip(); body=blocks[i+2]
    filename=re.search(r'^- Filename: `([^`]+)`', body, re.M)
    sha=re.search(r'^- SHA-256: `([^`]+)`', body, re.M)
    entries[order]={'title':title,'filename': filename.group(1) if filename else None,'sha256': sha.group(1) if sha else None}
problems=[]
for tr in report['tracks']:
    e=entries.get(tr['order'])
    if not e: problems.append((tr['order'],'missing concept entry')); continue
    if e['filename'] != tr['filename']: problems.append((tr['order'],'filename',e['filename'],tr['filename']))
    if e['sha256'] != tr['sha256']: problems.append((tr['order'],'sha256',e['sha256'],tr['sha256']))
print('concept entries',len(entries),'report tracks',len(report['tracks']),'problems',len(problems))
for p in problems[:20]: print(p)
